  function command(cmd){if(cmd==='close-panel'){closePanel();return;}if(cmd==='capture'){newCapture();return;}if(cmd==='screen'||cmd==='desktop'){newCapture(true);toast('已生成'+(cmd==='screen'?'当前屏幕':'整个桌面')+'的合成示例，未捕获真实屏幕。');return;}if(cmd==='open-image'){$('#fileInput').click();return;}if(cmd==='paste'){toast('粘贴仅模拟：已载入内置示例，未读取剪贴板。');S.imported=null;renderDocument();commit('粘贴合成示例');return;}if(cmd==='open-project'){$('#projectInput').click();return;}if(cmd==='save-project'){downloadText('Screenshot-liquid-demo.json',JSON.stringify({format:'screenshot-liquid-demo',version:1,document:snapshot()},null,2));toast('已保存演示 JSON；不是正式应用的项目格式，不包含导入图片。');return;}if(cmd==='history'){openPanel('history',panelOrigin);return;}if(cmd==='crop'){openPanel('crop',panelOrigin);return;}if(cmd==='apply-crop'){S.rect.w=clamp(Number($('#cropW').value)||40,40,stage.clientWidth-24);S.rect.h=clamp(Number($('#cropH').value)||30,30,stage.clientHeight-80);S.revision++;renderRect();closePanel();log('调整模拟裁剪几何');return;}if(cmd==='reset-position'){railManual=panelManual=false;positionRail();if(S.panel)placePanel(panelOrigin);toast('工具位置已恢复。');return;}if(cmd==='settings'){openSettings('capture');return;}if(cmd==='settings-service'){openSettings('services');return;}if(cmd==='terms'){openTerms();return;}if(cmd==='dismiss'){dismiss();return;}if(cmd==='run-ocr'){runTask('ocr');return;}if(cmd==='run-text-translate'){runTask('text');return;}if(cmd==='copy-source'||cmd==='copy-translation'){toast('模拟：'+(cmd==='copy-source'?'原文':'译文')+'已复制。未访问系统剪贴板。');return;}if(cmd==='source-box'){openModal('按源框校对',`<p>这是同一段合成文字的源框示例。选择一块后编辑文字。</p><div class="mock-list">${['The art of a quieter workspace.','A good tool responds to your intention.','It gives you room to think.'].map((x,i)=>`<div><strong>${i+1}. ${x}</strong><button data-source="${i}">选择</button></div>`).join('')}</div><label class="field"><span>当前块校正</span><textarea id="blockEdit">The art of a quieter workspace.</textarea></label><div class="modal-actions"><button class="primary" id="blockSave">保存校对</button></div>`);$$('[data-source]').forEach(b=>b.onclick=()=>{$('#blockEdit').value=b.previousElementSibling.textContent.slice(3);});$('#blockSave').onclick=()=>{S.source=$('#blockEdit').value;commit('源框校对');closeModal();openPanel('ocr',panelOrigin);};return;}if(cmd==='raw'){S.style=emptyStyle();renderDocument();commit('恢复原样');closePanel();return;}if(cmd==='save-style'){toast('当前样式已保留在本次演示；未写入应用配置。');return;}if(cmd==='delete-mark'){S.marks=S.marks.filter(m=>m.id!==S.selected);S.selected=null;renderMarks();commit('删除标注');closePanel();return;}if(cmd==='commit-text'){const text=$('#newText')?.value.trim();if(!text)return;const pos=S.textPoint||{x:180,y:230};S.marks.push({id:Date.now().toString(36),type:'text',x:pos.x,y:pos.y,x2:pos.x+160,y2:pos.y,color:'#3b82f6',fontSize:30,text});S.tool='select';S.selected=null;commit('放置文字 · 单次撤销');renderMarks();closePanel();stage.classList.remove('drawing');return;}if(cmd==='clear-history'){const rows=$$('#historyList [data-record]').filter(r=>r.querySelector('input').checked);if(!rows.length){toast('请先选择需要清理的示例记录。');return;}confirmDialog('清理所选 '+rows.length+' 条记录？','只删除演示条目，保留当前编辑。',()=>rows.forEach(r=>r.remove()));}}
  rail.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;hideTooltip();if(a==='complete'){runTask('complete');return;}if(a==='dismiss'){dismiss();return;}if(a==='undo'||a==='redo'){undo(a==='undo'?-1:1);return;}if(a==='translate'){closePanel(false);runTask('image');return;}if(a==='reader'){openReader(b);return;}if(['beauty','ocr','more'].includes(a)){if(S.panel===a)closePanel();else openPanel(a,b);return;}const prev=S.tool;S.tool=a;S.selected=null;transfer(prev,a);closePanel(false);stage.classList.toggle('drawing',a!=='select');renderMarks();syncRail();log('工具待命 · '+b.getAttribute('aria-label'));});
  // 所有合成异步任务都用文档身份、修订和任务对象保护，不允许旧结果触发成功或隐藏新截图。
  function cancelTask(announce=true){if(!S.task)return;S.task.cancelled=true;S.task=null;S.epoch++;$('#taskStatus').hidden=true;setPhase('editing');if(announce){toast('已取消任务，保留原图和当前编辑。');log('任务取消 · 迟到回调失效');}}
  async function runTask(kind){if(S.task||S.phase!=='editing')return;const fixture=$('#fixture').value;const job={kind,id:++S.epoch,documentId:S.documentId,revision:S.revision,cancelled:false};S.task=job;const label={ocr:'识别文字',text:'翻译文字',image:'翻译图片',complete:'完成截图'}[kind];setPhase(kind==='complete'?'completing':'processing');const status=$('#taskStatus');status.hidden=false;status.innerHTML=`<span class="loader"></span><span id="taskLabel">${kind==='complete'?'正在生成图片…':label+'…'}</span><button id="taskCancel">取消</button>`;$('#taskCancel').onclick=()=>cancelTask();const start=performance.now(),total=fixture==='slow'?T.demo.slowTaskMs:kind==='complete'?T.demo.commitMs:T.demo.taskMs;log(label+' · 等待模拟结果');
    while(performance.now()-start<total){await new Promise(r=>setTimeout(r,80));if(S.task!==job||job.cancelled||job.documentId!==S.documentId)return;const f=(performance.now()-start)/total;$('#taskLabel').textContent=kind==='complete'?(f<.55?'正在生成图片…':'等待复制确认…'):kind==='image'?(f<.35?'本地定位文字…':'翻译 '+Math.min(4,Math.ceil(f*4))+' / 4 块…'):label+' · '+Math.min(99,Math.floor(f*100))+'%';}
    if(S.task!==job)return;if(fixture==='stale')S.revision++;const current=job.documentId===S.documentId&&job.revision===S.revision&&job.id===S.epoch;S.task=null;status.hidden=true;setPhase('editing');if(!current){toast('已忽略过期结果，当前文档保持不变。',true);log(label+' · 身份不匹配，拒绝回填');return;}
    if(fixture==='failure'||kind==='complete'&&['partial','empty'].includes(fixture)){toast(kind==='complete'?'模拟复制失败：编辑现场保留，可以重试。':'模拟服务失败：保留已有结果，可以重试。',true);log(label+' · 失败，未播放成功退出');return;}if(kind==='complete'){log('模拟宿主确认成功 · 才开始退出');await finishSuccess();return;}if(fixture==='empty'){toast('没有发现新内容，原文和现有编辑已保留。');log(label+' · 空结果');return;}
    if(kind==='ocr'){S.source='The art of a quieter workspace.\nA good tool responds to your intention.\nIt gives you room to think, and gets out of the way.';commit('OCR 结果已回填（合成）');openPanel('ocr',rail.querySelector('[data-action="ocr"]'));}
    if(kind==='text'){S.translation='让工作空间，安静一点。\n好的工具，理解你的意图。\n它给思考留出空间，不打扰你的专注。';commit('文字翻译回填（合成）');openPanel('ocr',rail.querySelector('[data-action="ocr"]'));}
    if(kind==='image'){S.translated=true;commit('原位译文图层 · 单步撤销');renderDocument();}
    if(fixture==='partial'){toast('模拟：部分块失败，成功块保留；点击重试只演示补全反馈。',true);const retry=document.createElement('button');retry.textContent='重试';retry.style.fontSize='12px';retry.onclick=()=>{$('#fixture').value='success';$('#toast').hidden=true;runTask(kind);};$('#toast').prepend(retry);}else toast(kind==='image'?'已生成合成译文图层。点击“阅读译文”查看完整内容。':'模拟任务完成，结果可以校对。');log(label+' · '+(fixture==='partial'?'部分完成':'成功'));
  }
  async function finishSuccess(){const id=++S.epoch;setPhase('exiting');closePanel(false);closeReader(false);const cr=capture.getBoundingClientRect(),br=rail.querySelector('[data-action="complete"]').getBoundingClientRect(),dx=br.left+br.width/2-cr.left-cr.width/2,dy=br.top+br.height/2-cr.top-cr.height/2;const d=reduced()?T.motion.duration.reducedFade:T.motion.duration.exit;exitAnimations=[capture.animate(reduced()?[{opacity:1},{opacity:0}]:[{opacity:1,transform:'translate(0,0) scale(1)',borderRadius:'2px'},{opacity:0,transform:`translate(${dx}px,${dy}px) scale(.06)`,borderRadius:'80px'}],{duration:d,easing:'cubic-bezier(.4,0,.2,1)'}),rail.animate(reduced()?[{opacity:1},{opacity:0}]:[{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.90,.76)'}],{duration:d,easing:'cubic-bezier(.4,0,.2,1)'})];await Promise.all(exitAnimations.map(a=>a.finished.catch(()=>{})));if(id!==S.epoch)return;S.marks=[];S.source=S.translation='';S.translated=false;S.style=emptyStyle();S.documentId++;resetHistory();S.dismissed=false;hideWorkspace('本次截图已完成','模拟已复制。没有访问系统剪贴板；本次编辑已结束。');toast('模拟已复制 · 本次编辑结束');}
  function hideWorkspace(title,text){capture.hidden=rail.hidden=$('#shade').hidden=true;$('#panel').hidden=$('#reader').hidden=true;$('#resting').hidden=false;$('#restTitle').textContent=title;$('#restText').textContent=text;setPhase('hidden');resetMotion();}
  async function dismiss(){if(S.task){cancelTask();return;}if(S.phase!=='editing')return;const id=++S.epoch;setPhase('exiting');closePanel(false);closeReader(false);const a=rail.animate(reduced()?[{opacity:1},{opacity:0}]:[{opacity:1,translate:'0 0'},{opacity:0,translate:'0 8px'}],{duration:reduced()?100:180,easing:'ease-in'});await a.finished.catch(()=>{});if(id!==S.epoch)return;S.dismissed=true;hideWorkspace('编辑已收起','文档仍在本次演示中。恢复后继续编辑，不自动保存。');$('#resume').textContent='恢复编辑';log('收起 · 保留文档，不等于完成');}
  function restoreWorkspace(){S.epoch++;exitAnimations.forEach(a=>a.cancel());exitAnimations=[];$('#resting').hidden=true;capture.hidden=rail.hidden=$('#shade').hidden=false;$('#resume').textContent='再次截图';setPhase('editing');renderRect();renderDocument();resetMotion();requestAnimationFrame(()=>{measure();staticBody();});}
  function newCapture(immediate=false){cancelTask(false);S.epoch++;exitAnimations.forEach(a=>a.cancel());closeModal(false);closeReader(false);$('#panel').hidden=true;S.panel=null;lastCapture={rect:clone(S.rect),document:snapshot(),imported:S.imported};restoreWorkspace();S.tool='select';S.selected=null;stage.classList.remove('drawing');rail.hidden=true;$('#captureHint').hidden=false;setPhase('capturing');if(immediate){S.rect={x:24,y:46,w:stage.clientWidth-48,h:Math.min(stage.clientHeight-148,(stage.clientWidth-48)*.57)};acceptCapture();}else log('开始区域框选 · 拖动可选，Esc 保留旧文档');}
  function acceptCapture(){S.documentId++;S.revision=0;S.marks=[];S.translated=false;S.source=S.translation='';S.style=emptyStyle();S.imported=null;S.selected=null;S.tool='select';resetHistory();$('#captureHint').hidden=true;rail.hidden=false;railManual=panelManual=false;setPhase('editing');renderRect();renderDocument();const a=rail.animate(reduced()?[{opacity:0},{opacity:1}]:[{opacity:0,transform:'scale(.85,.74)'},{opacity:1,transform:'scale(1,1)'}],{duration:reduced()?100:260,easing:'cubic-bezier(.2,.8,.2,1)'});log('松手 · 可点已就绪，装饰继续落定');lastCapture=null;measure();staticBody();}
  function stagePoint(e){const r=stage.getBoundingClientRect();return{x:clamp(e.clientX-r.left,8,stage.clientWidth-8),y:clamp(e.clientY-r.top,34,stage.clientHeight-40)};}
  function imagePoint(e){const r=$('#marks').getBoundingClientRect();return{x:clamp((e.clientX-r.left)*1000/r.width,0,1000),y:clamp((e.clientY-r.top)*570/r.height,0,570)};}
  function beginGesture(e,type,data={}){if(e.button!==0||S.task)return;e.preventDefault();e.stopPropagation();hideTooltip();S.gesture={type,pointer:e.pointerId,start:stagePoint(e),imageStart:imagePoint(e),rect:clone(S.rect),before:snapshot(),...data};stage.setPointerCapture(e.pointerId);E.pointer.inside=false;wake();}
  stage.addEventListener('pointerdown',e=>{if(S.phase==='capturing'&&!e.target.closest('.stage-meta')){const p=stagePoint(e);beginGesture(e,'capture');S.rect={x:p.x,y:p.y,w:1,h:1};renderRect();}});
  $('#handles').innerHTML=[['nw',0,0],['n',50,0],['ne',100,0],['e',100,50],['se',100,100],['s',50,100],['sw',0,100],['w',0,50]].map(([a,x,y])=>`<button class="handle" data-handle="${a}" style="left:${x}%;top:${y}%;cursor:${a}-resize" aria-label="调整选区 ${a}"></button>`).join('');
  $('#handles').addEventListener('pointerdown',e=>{const h=e.target.closest('[data-handle]');if(h&&S.phase==='editing')beginGesture(e,'resize',{handle:h.dataset.handle});});
  $('#marks').addEventListener('pointerdown',e=>{if(S.phase!=='editing'||S.task)return;const pt=imagePoint(e),end=e.target.closest('[data-end]'),ann=e.target.closest('[data-id]');if(end){const mark=S.marks.find(m=>m.id===end.dataset.end);if(mark)beginGesture(e,'ann-resize',{id:mark.id,original:clone(mark)});return;}if(S.tool!=='select'){if(S.tool==='text'){e.preventDefault();e.stopPropagation();S.textPoint=pt;openPanel('text',rail.querySelector('[data-action="text"]'));return;}beginGesture(e,'draw',{draft:{id:Date.now().toString(36),type:S.tool,x:pt.x,y:pt.y,x2:pt.x,y2:pt.y,color:'#3b82f6',width:5}});return;}if(ann){const m=S.marks.find(m=>m.id===ann.dataset.id);if(m){S.selected=m.id;beginGesture(e,'ann-move',{id:m.id,original:clone(m)});renderMarks();openPanel('properties',rail.querySelector('[data-action="select"]'));}return;}S.selected=null;renderMarks();beginGesture(e,'move');});
  stage.addEventListener('pointermove',e=>{const g=S.gesture;if(!g||g.pointer!==e.pointerId)return;const p=stagePoint(e),ip=imagePoint(e),dx=p.x-g.start.x,dy=p.y-g.start.y;if(g.type==='capture'){S.rect={x:Math.min(p.x,g.start.x),y:Math.min(p.y,g.start.y),w:Math.max(1,Math.abs(dx)),h:Math.max(1,Math.abs(dy))};renderRect();}else if(g.type==='move'){S.rect={...g.rect,x:g.rect.x+dx,y:g.rect.y+dy};renderRect();}else if(g.type==='resize'){const r={...g.rect},a=g.handle;if(a.includes('e'))r.w=Math.max(40,g.rect.w+dx);if(a.includes('s'))r.h=Math.max(30,g.rect.h+dy);if(a.includes('w')){r.x=Math.min(g.rect.x+g.rect.w-40,g.rect.x+dx);r.w=g.rect.x+g.rect.w-r.x;}if(a.includes('n')){r.y=Math.min(g.rect.y+g.rect.h-30,g.rect.y+dy);r.h=g.rect.y+g.rect.h-r.y;}r.w=Math.min(r.w,stage.clientWidth-16);r.h=Math.min(r.h,stage.clientHeight-78);S.rect=r;renderRect();}else if(g.type==='draw'){g.draft.x2=ip.x;g.draft.y2=ip.y;renderMarks();}else if(g.type==='ann-move'){const m=S.marks.find(m=>m.id===g.id);if(m){const dx=ip.x-g.imageStart.x,dy=ip.y-g.imageStart.y;m.x=clamp(g.original.x+dx,0,1000);m.y=clamp(g.original.y+dy,0,570);m.x2=clamp(g.original.x2+dx,0,1000);m.y2=clamp(g.original.y2+dy,0,570);renderMarks();}}else if(g.type==='ann-resize'){const m=S.marks.find(m=>m.id===g.id);if(m){m.x2=ip.x;m.y2=ip.y;renderMarks();}}});
  function endGesture(e,cancel=false){const g=S.gesture;if(!g||e&&g.pointer!==e.pointerId)return;S.gesture=null;if(stage.hasPointerCapture(g.pointer))stage.releasePointerCapture(g.pointer);if(cancel){S.rect=g.rect;applySnapshot(g.before);renderRect();log('手势取消 · 未写入历史');return;}if(g.type==='capture'){if(S.rect.w<16||S.rect.h<16){S.rect=g.rect;renderRect();return;}acceptCapture();}else if(g.type==='draw'){if(Math.hypot(g.draft.x2-g.draft.x,g.draft.y2-g.draft.y)<8)return;S.marks.push(g.draft);S.selected=g.draft.id;S.tool='select';stage.classList.remove('drawing');commit('手绘标注 · 单次撤销');renderMarks();openPanel('properties',rail.querySelector('[data-action="select"]'));}else if(g.type.startsWith('ann'))commit('调整标注');else{S.revision++;log('选区调整 · 几何直接跟手');}renderMarks();syncRail();}
  stage.addEventListener('pointerup',e=>endGesture(e));stage.addEventListener('pointercancel',e=>endGesture(e,true));stage.addEventListener('lostpointercapture',e=>{if(S.gesture)endGesture(e,true);});
  capture.addEventListener('keydown',e=>{if(S.task||e.target!==capture||!e.key.startsWith('Arrow'))return;e.preventDefault();const d=e.ctrlKey?10:1,dx=e.key==='ArrowLeft'?-d:e.key==='ArrowRight'?d:0,dy=e.key==='ArrowUp'?-d:e.key==='ArrowDown'?d:0;if(e.shiftKey){S.rect.w=clamp(S.rect.w+dx,40,stage.clientWidth-24);S.rect.h=clamp(S.rect.h+dy,30,stage.clientHeight-78);}else{S.rect.x+=dx;S.rect.y+=dy;}S.revision++;renderRect();});
  // 浮卡、工具轨、阅读窗均独立拖动；手动坐标只留在界面层，不写入演示项目。
  let uiDrag=null;
  function startUiDrag(e,el,kind){if(e.button!==0||e.target.closest('button,input,select,textarea')&&e.target!==$('#railGrip')&&kind!=='reader-resize')return;e.preventDefault();e.stopPropagation();uiDrag={el,kind,id:e.pointerId,x:e.clientX,y:e.clientY,left:parseFloat(el.style.left)||0,top:parseFloat(el.style.top)||0,width:el.offsetWidth,height:el.offsetHeight};el.setPointerCapture(e.pointerId);$('#panelLink').innerHTML='';E.pointer.inside=false;wake();}
  $('#railGrip').onpointerdown=e=>startUiDrag(e,rail,'rail');
  $('#panel').addEventListener('pointerdown',e=>{if(e.target.closest('[data-drag="panel"]'))startUiDrag(e,$('#panel'),'panel');});
  $('#reader').addEventListener('pointerdown',e=>{if(e.target.closest('.reader-resize'))startUiDrag(e,$('#reader'),'reader-resize');else if(e.target.closest('header'))startUiDrag(e,$('#reader'),'reader');});
  addEventListener('pointermove',e=>{const d=uiDrag;if(!d||d.id!==e.pointerId)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(d.kind==='reader-resize'){d.el.style.width=clamp(d.width+dx,Math.min(T.layout.readerMinWidth,stage.clientWidth-24),stage.clientWidth-24)+'px';d.el.style.height=clamp(d.height+dy,240,stage.clientHeight-24)+'px';renderReaderText();}else{d.el.style.left=clamp(d.left+dx,8,stage.clientWidth-d.el.offsetWidth-8)+'px';d.el.style.top=clamp(d.top+dy,8,stage.clientHeight-d.el.offsetHeight-8)+'px';}if(d.kind==='rail'){railManual=true;E.dirty=true;}if(d.kind==='panel')panelManual=true;if(d.kind.startsWith('reader'))saveReaderBounds();});
  function stopUiDrag(e,cancel=false){if(!uiDrag||e&&uiDrag.id!==e.pointerId)return;const d=uiDrag;uiDrag=null;if(cancel){Object.assign(d.el.style,{left:d.left+'px',top:d.top+'px',width:d.width+'px',height:d.height+'px'});}if(d.el.hasPointerCapture(d.id))d.el.releasePointerCapture(d.id);E.dirty=true;saveReaderBounds();}
  addEventListener('pointerup',e=>stopUiDrag(e));addEventListener('pointercancel',e=>stopUiDrag(e,true));
  function keyMove(el,e){if(!e.key.startsWith('Arrow'))return;e.preventDefault();const step=e.shiftKey?24:8,x=(parseFloat(el.style.left)||0)+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),y=(parseFloat(el.style.top)||0)+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0);el.style.left=clamp(x,8,stage.clientWidth-el.offsetWidth-8)+'px';el.style.top=clamp(y,8,stage.clientHeight-el.offsetHeight-8)+'px';if(el===rail)railManual=true;if(el===$('#panel'))panelManual=true;E.dirty=true;saveReaderBounds();}
  $('#railGrip').onkeydown=e=>keyMove(rail,e);$('#panel').addEventListener('keydown',e=>{if(e.target.matches('[data-drag="panel"]'))keyMove($('#panel'),e);});
  const readerParagraphs=[['The art of a quieter workspace.','让工作空间，安静一点。'],['A good tool responds to your intention. It gives you room to think, and gets out of the way.','好的工具，理解你的意图。它给思考留出空间，不打扰你的专注。'],['Less noise. More intention. A little movement can make an interaction easier to understand.','少一点噪声，多一点意图。微小而准确的运动，能让一次交互更容易被理解。'],['Made to feel effortless. When the work is done, the interface returns quietly to rest.','让操作自然发生。工作完成之后，界面安静地回到休息状态。']];
  function openReader(origin){if(!S.translated||S.task)return;closePanel(false);const el=$('#reader');el.hidden=false;el.innerHTML=`<header tabindex="0" aria-label="移动阅读窗口，方向键微调"><span class="grip">⠿</span><h2>阅读译文</h2><button class="quiet" id="readerReset" aria-label="恢复阅读窗口位置">↺</button><button class="close" id="readerClose" aria-label="关闭阅读窗口">×</button></header><div class="reader-toolbar"><div class="pill-row"><button class="pill${!S.compare?' on':''}" id="readTarget">译文</button><button class="pill${S.compare?' on':''}" id="readCompare">对照</button></div><div class="reader-type"><button id="fontDown" aria-label="减小字号">−</button><span id="readerFontLabel">${S.readerFont}px</span><button id="fontUp" aria-label="增大字号">＋</button></div></div><div class="reader-content" tabindex="0"></div><button class="reader-resize" aria-label="调整阅读窗口大小，方向键调整">◢</button>`;const b=S.readerBounds||{x:clamp((stage.clientWidth-T.layout.readerPreferredWidth)/2,12,stage.clientWidth-320),y:28,w:Math.min(T.layout.readerPreferredWidth,stage.clientWidth-24),h:Math.min(T.layout.readerPreferredHeight,stage.clientHeight-56)};Object.assign(el.style,{left:Math.max(12,b.x)+'px',top:b.y+'px',width:b.w+'px',height:b.h+'px'});stage.classList.toggle('full-reading',stage.clientWidth<670);renderReaderText();$('#readerClose').onclick=()=>closeReader();$('#readerReset').onclick=()=>{S.readerBounds=null;openReader();};$('#readTarget').onclick=()=>{S.compare=false;renderReaderText();};$('#readCompare').onclick=()=>{S.compare=true;renderReaderText();};$('#fontDown').onclick=()=>{S.readerFont=clamp(S.readerFont-2,16,28);renderReaderText();};$('#fontUp').onclick=()=>{S.readerFont=clamp(S.readerFont+2,16,28);renderReaderText();};el.querySelector('header').onkeydown=e=>keyMove(el,e);el.querySelector('.reader-resize').onkeydown=e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();el.style.width=clamp(el.offsetWidth+(e.key==='ArrowRight'?16:e.key==='ArrowLeft'?-16:0),Math.min(300,stage.clientWidth-24),stage.clientWidth-24)+'px';el.style.height=clamp(el.offsetHeight+(e.key==='ArrowDown'?16:e.key==='ArrowUp'?-16:0),240,stage.clientHeight-24)+'px';saveReaderBounds();renderReaderText();};el.animate([{opacity:0},{opacity:1}],{duration:reduced()?100:180});$('#readerClose').focus({preventScroll:true});log('阅读窗口 · 文本不变形，保留原位截图');}
  function renderReaderText(){const el=$('#reader');if(el.hidden)return;const body=el.querySelector('.reader-content');body.style.fontSize=S.readerFont+'px';body.className='reader-content'+(S.compare?' comparing':'')+(el.offsetWidth<640?' narrow':'');body.innerHTML=readerParagraphs.map(([a,b],i)=>`<article>${S.compare?`<div class="source">${escapes(a)}</div>`:''}<div>${i===0?'<h3>'+b+'</h3>':b}</div></article>`).join('');$('#readerFontLabel').textContent=S.readerFont+'px';$('#readTarget').classList.toggle('on',!S.compare);$('#readCompare').classList.toggle('on',S.compare);$('#fontDown').disabled=S.readerFont<=16;$('#fontUp').disabled=S.readerFont>=28;}
  function saveReaderBounds(){const el=$('#reader');if(el.hidden)return;S.readerBounds={x:parseFloat(el.style.left),y:parseFloat(el.style.top),w:el.offsetWidth,h:el.offsetHeight};}
