  function openModal(title,body,tabs=''){modalSerial++;modalReturn=document.activeElement;const el=$('#modalRoot');el.hidden=false;el.innerHTML=`<section class="modal clay" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header><h2 id="modalTitle">${title}</h2><button class="close" id="modalClose" aria-label="关闭对话框">×</button></header>${tabs}<div class="modal-body">${body}</div></section>`;$('.shell').inert=true;$('.mast').inert=true;E.pointer.inside=false;wake();hideTooltip();$('#modalClose').onclick=()=>closeModal();el.querySelector('.modal').animate(reduced()?[{opacity:0},{opacity:1}]:[{opacity:0,transform:'translateY(7px) scale(.98)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:reduced()?100:220,easing:'cubic-bezier(.2,.8,.2,1)'});$('#modalClose').focus({preventScroll:true});}
